package com.acme.core.infrastructure.persistence;

import com.acme.core.application.dictionary.DictionaryPort;
import com.acme.core.application.organization.DepartmentPort;
import com.acme.core.application.product.ProductPort;
import com.acme.core.application.product.ProductService;
import com.acme.core.infrastructure.persistence.mapper.ProductMapper;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * Product reference bean wiring (generated by engineering-platform 0.1.0).
 */
@Configuration
public class ProductBeansConfig {

    @Bean
    public ProductPort productPort(ProductMapper productMapper, DepartmentPort departmentPort) {
        return new MybatisProductRepository(productMapper, departmentPort);
    }

    @Bean
    public ProductService productService(ProductPort productPort, DictionaryPort dictionaryPort) {
        return new ProductService(productPort, dictionaryPort);
    }
}
